from pathlib import Path
TODAY='2026-06-18'

def header(title): return f"# {title}\n\n> - 引用级别：✅可供学习参考\n> - 最后更新：{TODAY}\n\n"
def write(path,text): Path(path).write_text(text.strip()+"\n", encoding='utf-8')
def article(title,path,pos,concepts,asks,triage,cats,scenarios,analysis):
 c='\n\n'.join(f"### {i+1}. {h}\n\n{b}" for i,(h,b) in enumerate(concepts)); a='\n'.join(f"- {x}" for x in asks)
 t='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} | {x[3]} |" for x in triage); ca='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} |" for x in cats)
 sc='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} |" for x in scenarios); an='\n'.join(f"- **{k}：** {v}" for k,v in analysis)
 write(path, header(title)+f'''## 一句话定位\n\n{pos}\n\n## 一、准确解释：三个概念分别是什么\n\n{c}\n\n## 二、药店咨询首先要问什么\n\n{a}\n\n## 三、轻症、需药师判断、应就医的分层\n\n| 分层 | 典型表现 | 药店/平台可以做什么 | 不应做什么 |\n|---|---|---|---|\n{t}\n\n## 四、常见品类与药店咨询口径\n\n| 品类/服务 | 适合讨论的场景 | 药师提醒点 |\n|---|---|---|\n{ca}\n\n## 五、即时零售医药场景拆解\n\n| 场景 | 用户需求 | 平台/药店承接点 |\n|---|---|---|\n{sc}\n\n## 六、对平台、药店、药企的业务分析\n\n{an}\n''')

def chronic(title,path,disease,metric,complications,redflag,drug_classes,monitor_items):
 pos=f'本文回答：{disease}是什么，它为什么适合形成药店慢病复购、监测用品和药师随访场景。核心判断是：{disease}不是一次性买药问题，而是围绕{metric}、长期依从性、并发症预防和复诊监测形成的慢病管理场景；即时零售可以提高可得性，但不能替代医生调整治疗。'
 concepts=[(f'{disease}：核心不是症状，而是长期风险管理',f'{disease}往往早期症状不典型，用户可能因为体检指标、医生诊断或长期处方进入药店复购。文章应把它理解为长期管理对象，而不是用户有明显不适才需要关注。'),(f'{metric}：药店咨询的关键观察点',f'{metric}用于判断控制状态和随访需求。药店不能替代检验和诊断，但可以提醒用户记录指标、按医嘱复诊，并识别异常变化。'),('并发症和合并用药：决定服务深度',f'{disease}常与{complications}相关。用户可能同时使用多种药，药店咨询要关注依从性、不良反应、重复用药和相互作用。'),('慢病复购：不断药不等于管得好','慢病复购要看是否按医嘱、是否定期监测、是否出现不良反应和是否需要复诊。平台只解决买到药，不能证明疾病控制良好。')]
 asks=[f'最近一次{metric}结果、监测频率和是否达成医生设定目标。','是否按医嘱用药，有无漏服、自行停药或自行换药。',f'是否存在{redflag}等需要就医的信号。','是否合并其他慢病、肝肾功能异常、妊娠或多药联用。','是否需要监测用品、处方续配、医保支付或药师随访。']
 triage=[('稳定复购','已有诊断和处方，指标相对稳定','复购提醒、监测用品、依从性教育','不自行调整处方'),('药师重点判断','指标波动、漏服、不良反应或多药联用','核对用药和复诊需求，提醒监测','不替代医生调药'),('优先就医',redflag,'提示就医或联系医生','不引导仅靠买药处理')]
 cats=[(drug_classes,'已有医生诊断和处方的长期治疗','不自行启停或替换，关注不良反应'),('监测用品',monitor_items,'记录趋势并提示异常，不替代诊断'),('生活方式支持','饮食、运动、体重、戒烟限酒等教育','作为辅助管理，不替代药物和复诊'),('药师随访','复购、漏服、不良反应、相互作用','形成慢病服务记录')]
 scenarios=[('慢病复购','不想断药','处方/医保/复诊提醒'),('指标监测','想知道控制情况','监测用品、记录工具'),('异常提醒','指标明显异常或症状加重','提示就医'),('联合用药','多病共存','药师核对相互作用')]
 analysis=[('平台','慢病入口要围绕复购、处方、医保、监测和随访，而不是只做低价补货。'),('药店','药师价值在依从性、不良反应和复诊提醒，不是简单收银。'),('药企','慢病药企适合做患者教育和依从性项目，不能把复购等同于控制达标。')]
 article(title,path,pos,concepts,asks,triage,cats,scenarios,analysis)

chronic('高血压基础概念与慢病复购场景','08-疾病与医学基础/补充资料/高血压基础概念与慢病复购场景.md','高血压','家庭血压、诊室血压和心脑血管风险','冠心病、卒中、肾病、糖尿病和高脂血症','血压极高伴胸痛、呼吸困难、神经系统症状、意识异常或孕期高血压','降压药相关长期用药','家庭血压计、血压记录和复诊提醒')
chronic('糖尿病基础概念与慢病管理场景','08-疾病与医学基础/补充资料/糖尿病基础概念与慢病管理场景.md','糖尿病','空腹/餐后血糖、糖化血红蛋白和低血糖风险','心血管疾病、肾病、视网膜病变、神经病变和足部问题','严重低血糖、意识异常、酮症风险、感染伤口或孕期血糖异常','降糖药、胰岛素及相关处方药','血糖仪、试纸、针头、足部护理和饮食记录')
chronic('高脂血症基础概念与用药依从性','08-疾病与医学基础/补充资料/高脂血症基础概念与用药依从性.md','高脂血症','LDL-C、甘油三酯和ASCVD总体风险','冠心病、卒中、糖尿病、高血压和脂肪肝','胸痛、卒中样症状、严重肌痛伴尿色异常或肝功能异常','调脂药相关长期用药','血脂化验复查提醒、体重和饮食记录')
chronic('慢性肾病基础概念','08-疾病与医学基础/补充资料/慢性肾病基础概念.md','慢性肾病','eGFR、尿蛋白、血压和电解质风险','高血压、糖尿病、贫血、骨代谢异常和心血管风险','少尿、明显水肿、呼吸困难、严重乏力、疑似高钾或肾功能快速恶化','肾病相关处方药和需调剂量药物','血压、体重、水肿、尿蛋白和复诊记录')

# COPD asthma
article('COPD与哮喘基础概念','08-疾病与医学基础/补充资料/COPD与哮喘基础概念.md','本文回答：COPD和哮喘分别是什么，为什么二者都适合做吸入装置教育、急性加重识别和慢病复购。核心判断是：COPD更常与长期吸烟/暴露和持续气流受限相关，哮喘更强调可变气流受限和诱因波动；平台可以承接吸入药复购和装置教育，但不能替代肺功能诊断和急性发作处理。',
[('COPD：长期气道/肺损伤导致的慢性呼吸问题','COPD常表现为长期咳嗽、咳痰、活动后气短和反复加重，常与吸烟、职业粉尘、空气污染等长期暴露相关。它不是普通咳嗽，管理重点是戒烟、吸入药依从性、急性加重识别和肺功能随访。'),('哮喘：可变的气道炎症和气道狭窄','哮喘常表现为反复喘息、胸闷、咳嗽和夜间/清晨症状，可能由过敏、运动、感染、冷空气或刺激物诱发。患者可能平时正常，发作时迅速加重。'),('吸入药和吸入装置：疗效高度依赖使用方法','吸入治疗不是“买到药就有效”，装置类型、吸入动作、清洁、漱口和依从性都会影响疗效。药店服务价值在于演示和纠错。'),('急性加重：平台必须优先识别风险','呼吸困难加重、说话困难、口唇发紫、血氧下降或救急药无效时，配送药品不能替代急救评估。')],
['诊断是COPD、哮喘还是仅有咳喘症状，是否做过肺功能。','症状频率、夜间症状、活动受限和近期急性加重次数。','正在使用的吸入药名称、装置类型、用法和是否漏用。','是否有呼吸困难、胸痛、血氧下降、口唇发紫或说话困难。','吸烟史、过敏史、感染诱因和是否有急救药。'],
[('稳定复购','已有诊断，按医嘱使用吸入药','复购提醒、装置教育、漱口提醒','不自行停用控制药'),('药师重点判断','咳喘反复、装置不会用、用药不规律','演示装置、核对处方和急救药','不把咳嗽都当哮喘'),('优先就医','明显呼吸困难、口唇发紫、血氧低、救急药无效','提示急诊','不等待配送')],
[('吸入控制药','长期控制炎症/气道症状','强调规律使用和漱口'),('急救吸入药','急性喘息缓解','频繁使用提示控制不佳需就医'),('雾化/辅助器具','特定医嘱或装置辅助','核对适用人群和清洁'),('戒烟/监测用品','COPD风险管理','作为长期管理辅助')],
[('吸入药复购','避免断药','处方/库存/用法提醒'),('装置教育','用户不会吸','视频/药师演示'),('急性加重','呼吸困难加重','就医提示优先'),('季节诱发','冷空气、感染、过敏','提前备药和随访提醒')],
[('平台','应把吸入装置教育做成内容组件，咳喘搜索要先识别急性呼吸困难。'),('药店','药师演示吸入装置和识别急性加重，比单纯卖药更有价值。'),('药企','吸入药企业应重视患者教育、装置依从性和复购管理。')])

# allergy eye insomnia etc concise targeted
article('结膜炎眼干眼部不适基础概念','08-疾病与医学基础/补充资料/结膜炎眼干眼部不适基础概念.md','本文回答：结膜炎、眼干和眼部不适如何在药店咨询中区分。核心判断是：眼部症状适合即时零售承接人工泪液、护理用品和药师咨询，但视力下降、眼痛、畏光、外伤和隐形眼镜相关风险必须优先就医。',
[('结膜炎：眼红分泌物不等于都能自购眼药水','结膜炎可能与病毒、细菌、过敏或刺激有关。不同类型处理不同，药店不能仅凭“眼红”推荐抗菌眼药。'),('眼干：常与泪膜不稳定和环境/屏幕使用相关','眼干常表现为干涩、异物感、疲劳、烧灼感。人工泪液和环境改善可用于轻症支持，但持续疼痛或视力变化需就医。'),('眼部不适：先排除危险信号','眼痛、畏光、视力下降、外伤、化学品接触、隐形眼镜相关感染风险都不能当作普通眼干。'),('三者关系','眼红、眼干、异物感可以重叠，但感染、过敏、干眼和眼外伤是不同路径。')],
['单眼还是双眼，是否视力下降、眼痛、畏光。','是否有分泌物、瘙痒、过敏史或接触刺激物。','是否佩戴隐形眼镜，是否有外伤或化学品接触。','症状持续时间和是否反复。','已使用哪些眼药水，是否含抗菌、激素或防腐剂。'],
[('轻症','轻度干涩、短期疲劳、无视力变化','人工泪液、护理建议、药师咨询','不推荐处方眼药'),('药师重点判断','眼红分泌物、过敏瘙痒、反复发作','追问类型和风险，必要时就医','不滥用抗菌/激素眼药'),('优先就医','视力下降、眼痛、畏光、外伤、化学品、隐形眼镜感染风险','提示眼科就医','不靠自购眼药处理')],
[('人工泪液','轻度眼干、屏幕疲劳','注意防腐剂和使用频次'),('抗过敏眼部用品','过敏性瘙痒流泪','症状严重或视力影响需就医'),('眼部清洁护理','轻度刺激或护理','不替代感染评估'),('处方眼药','医生诊断后使用','不自行购买或长期使用')],
[('急用眼药','眼干不适','附近库存+红旗提示'),('屏幕疲劳','长期干涩','人工泪液和行为建议'),('过敏季','眼痒流泪','抗过敏咨询'),('风险拦截','视力下降或眼痛','眼科就医')],
[('平台','眼部入口必须强提示视力下降、眼痛、隐形眼镜风险。'),('药店','药师要区分干眼、过敏、感染和外伤，不应只推荐眼药水。'),('药企','眼科产品教育应强调适用场景和就医信号。')])

article('过敏鼻炎皮炎湿疹基础概念','08-疾病与医学基础/补充资料/过敏鼻炎皮炎湿疹基础概念.md','本文回答：过敏性鼻炎、皮炎和湿疹这些过敏相关场景如何区分。核心判断是：过敏类需求高频且适合即时零售承接，但呼吸困难、面唇肿胀、全身风团和感染性皮损必须优先就医。',
[('过敏性鼻炎：鼻部过敏反应，不是普通感冒','典型表现为打喷嚏、清水样鼻涕、鼻痒、鼻塞，可伴眼痒。它常与花粉、尘螨、宠物、季节变化有关。'),('皮炎/湿疹：皮肤屏障和炎症问题','常表现为瘙痒、红斑、干燥、脱屑、渗出或反复发作。护理、保湿和避免诱因很重要。'),('急性过敏反应：必须识别全身风险','面唇舌肿胀、呼吸困难、喉头紧、全身风团或头晕可能提示严重过敏反应。'),('三者关系','鼻炎、皮炎、湿疹都可与过敏体质相关，但用药和风险不同。')],
['鼻部症状还是皮肤症状，是否季节性或接触诱因。','皮疹范围、是否渗出感染、是否眼周或面部明显肿胀。','是否呼吸困难、面唇舌肿胀或全身风团。','儿童、孕妇、哮喘患者和既往严重过敏史。','已用抗过敏药、外用激素或抗生素情况。'],
[('轻症','轻度鼻痒流涕或局部干痒皮疹','抗过敏/保湿/护理咨询','不长期自行用强效外用药'),('药师重点判断','反复发作、儿童、面部皮疹或用药不清','询问诱因和用药史，必要时就医','不把感染当过敏'),('优先就医','呼吸困难、面唇肿胀、全身风团、渗出感染严重','提示就医','不只推荐抗过敏药')],
[('口服抗过敏药','鼻痒、喷嚏、皮肤瘙痒','注意嗜睡和特殊人群'),('鼻喷/眼部抗过敏','鼻炎或眼痒','按说明书使用'),('保湿修复','湿疹/干燥皮肤','长期护理，避免刺激'),('外用药','皮炎湿疹局部处理','部位、强度和疗程需谨慎')],
[('季节过敏','花粉季鼻炎眼痒','提前备药和诱因教育'),('皮肤急用','瘙痒红斑','保湿/外用咨询'),('儿童过敏','家长不确定','剂型和就医提示'),('严重过敏','呼吸/肿胀风险','就医优先')],
[('平台','过敏入口要区分鼻炎、皮肤和严重过敏反应。'),('药店','药师应识别感染性皮损和严重过敏，不只推荐止痒药。'),('药企','适合做过敏诱因、说明书和长期护理教育。')])

